Rationale: The Fredkin gate swaps the two target bits iff the control is 1, otherwise leaves them. It is reversible and conserves Hamming weight. Enumerate all 3-bit inputs, apply cswap, and compare to the expected conditional swap.

```python
from qiskit import QuantumCircuit
from qiskit.quantum_info import Statevector

def fredkin_out(c, a, b):
    qc = QuantumCircuit(3)
    if c: qc.x(0)
    if a: qc.x(1)
    if b: qc.x(2)
    qc.cswap(0, 1, 2)
    out = next(k for k, v in Statevector(qc).probabilities_dict().items() if v > 0.5)
    bits = list(map(int, out[::-1]))   # [q0,q1,q2]
    return bits

if __name__ == "__main__":
    for c in (0, 1):
        for a in (0, 1):
            for b in (0, 1):
                bits = fredkin_out(c, a, b)
                expected = [c, (b if c else a), (a if c else b)]
                assert bits == expected, (c, a, b, bits, expected)
                assert sum(bits) == c + a + b      # weight preserved
    print("Fredkin truth table verified")
```

Rationale: Qiskit's FullAdderGate / built-in adder implements a Cuccaro-style ripple-carry addition that produces an (n+1)-bit sum including the carry. Encode the inputs as basis states, run the adder, and read the sum register to confirm exact integer addition.

```python
from qiskit import QuantumCircuit
from qiskit.circuit.library import CDKMRippleCarryAdder
from qiskit.quantum_info import Statevector

def ripple_add(a, b, n):
    adder = CDKMRippleCarryAdder(n, kind="full")
    qc = QuantumCircuit(adder.num_qubits)
    # qubit layout: [cin, a0..a{n-1}, b0..b{n-1}, cout]
    for i in range(n):
        if (a >> i) & 1: qc.x(1 + i)
        if (b >> i) & 1: qc.x(1 + n + i)
    qc.compose(adder, inplace=True)
    out = next(k for k, v in Statevector(qc).probabilities_dict().items() if v > 0.5)
    bits = out[::-1]
    b_bits = bits[1 + n:1 + 2 * n]
    cout = bits[1 + 2 * n]
    return int((cout + b_bits[::-1]), 2)

if __name__ == "__main__":
    n = 3
    for a in range(8):
        for b in range(8):
            assert ripple_add(a, b, n) == a + b, (a, b, ripple_add(a, b, n))
    print("Ripple-carry adder verified for all 3-bit operand pairs")
```

Rationale: A distance-5 repetition code encodes |b> as |bbbbb> and corrects any error of weight <= 2 by majority decoding. For computational basis inputs this reduces to classical majority over the five physical bits; verify exhaustively over all weight<=2 error patterns.

```python
import itertools
from qiskit import QuantumCircuit
from qiskit.quantum_info import Statevector

def encode_and_error(bit, error_qubits):
    qc = QuantumCircuit(5)
    if bit: qc.x(0)
    qc.cx(0, 1); qc.cx(0, 2); qc.cx(0, 3); qc.cx(0, 4)
    for q in error_qubits:
        qc.x(q)
    out = next(k for k, v in Statevector(qc).probabilities_dict().items() if v > 0.5)
    return out[::-1]                          # physical bits q0..q4

def majority(bits):
    return 1 if bits.count("1") >= 3 else 0

if __name__ == "__main__":
    for bit in (0, 1):
        for w in (0, 1, 2):
            for combo in itertools.combinations(range(5), w):
                bits = encode_and_error(bit, combo)
                assert majority(bits) == bit, (bit, combo, bits)
    print("Distance-5 repetition code corrects all weight<=2 errors; verified")
```
